/* Shared office shell. Project records stay in this browser. No model calls. */
const emptyCampaign=()=>({title:'',brief:'',step:0,approved:false});
let projects=[{id:'general',name:'Dự án mẫu',knowledge:'Đây là khuôn Marketing dùng chung. Thêm brief sản phẩm, khách hàng, kênh và mục tiêu của từng dự án.',campaign:emptyCampaign()},{id:'gfkey',name:'GFKey',knowledge:'Nguồn: trang GFKey sản phẩm và tài liệu GreenFi do người dùng cung cấp.\nGFKey: mã định danh và quyền truy cập hệ sinh thái. Phi Phi: trợ lý đầu mối trong nhóm 18 trợ lý được mô tả trong tài liệu.\nCác nhóm sản phẩm được mô tả: trợ lý AI, xưởng sáng tạo, mạng xã hội chuyên gia, kết nối, cộng đồng, tin tức.\nNhóm khách hàng được nêu: gia đình Việt, chuyên gia/người tạo nội dung, cán bộ cấp xã, đối tác phân phối.\nGiá, ưu đãi và chính sách cần xác nhận phiên bản trước khi đưa vào nội dung. Quy chế KPI và cơ chế đại lý là tài liệu nội bộ. GFSign và G-NEXS là đề án/bản mẫu riêng, không mặc định là tính năng đang vận hành.\nChưa kiểm chứng tính năng trên hệ thống thật; không đưa cam kết bảo mật tuyệt đối hoặc thu nhập đảm bảo vào nội dung.',campaign:emptyCampaign()}];let projectId='general',motion=true;
try{const saved=JSON.parse(localStorage.getItem('tram-projects-v1'));if(saved&&Array.isArray(saved.projects)&&saved.projects.length&&saved.projects.every(p=>typeof p.id==='string'&&typeof p.name==='string'&&typeof p.knowledge==='string'&&p.campaign&&typeof p.campaign.title==='string'&&typeof p.campaign.brief==='string'&&Number.isInteger(p.campaign.step)&&p.campaign.step>=0&&p.campaign.step<=11)){projects=saved.projects;projectId=projects.some(p=>p.id===saved.active)?saved.active:projects[0].id;motion=saved.motion!==false}}catch{}
const currentProject=()=>projects.find(p=>p.id===projectId);
state={...currentProject().campaign};
const originalRender=render;const originalPersist=persist;
persist=function(){currentProject().campaign={...state};try{localStorage.setItem('tram-projects-v1',JSON.stringify({projects,active:projectId,motion}))}catch{}};
document.title='Trạm Marketing · Văn phòng AI';
$('.logo').innerHTML='<span class="brand-icon">✳</span><span>TRẠM<span class="tiny">MARKETING AI OFFICE</span></span>';
$('.side-label').textContent='ĐỘI NGŨ DÙNG CHUNG';
document.querySelector('header').innerHTML='<div class="breadcrumb">Trạm <b>/ Marketing</b></div><div class="project-tools"><label class="sr-only" for="projectSelect">Dự án đang làm việc</label><select id="projectSelect"></select><button id="addProject" title="Thêm dự án" aria-label="Thêm dự án">＋</button><span class="badge">DEMO · Mô phỏng</span></div>';
$('.eyebrow').textContent='MỘT ĐỘI NGŨ · NHIỀU DỰ ÁN';$('h1').innerHTML='Một trạm. Cả đội ngũ.<span class="live">● Phi Phi Office</span>';
$('.heading p').textContent='Giao mục tiêu. Xem Phi Phi phối hợp. Bạn giữ quyền quyết định.';
$('.side-bottom').innerHTML='<span class="dot"></span> PHI PHI TEAM<p>11 vai trò · Dữ liệu theo dự án</p>';
const nav=document.createElement('button');nav.className='nav';nav.dataset.view='knowledge';nav.textContent='◈   Tri thức dự án';document.querySelector('body>aside').insertBefore(nav,$('.side-bottom'));
const knowledge=document.createElement('div');knowledge.id='knowledge';knowledge.className='hidden';$('#results').after(knowledge);
const toolbar=document.createElement('div');toolbar.className='scene-tools';toolbar.innerHTML='<span>✳ Phi Phi · Mẫu nhân vật 01</span><div><button id="characterStandard">Mẫu tiêu chuẩn</button><button id="motionToggle">Ⅱ Dừng chuyển động</button></div>';$('#office').before(toolbar);
const projectDialog=document.createElement('dialog');projectDialog.id='projectDialog';projectDialog.innerHTML='<button class="close" aria-label="Đóng">×</button><div class="eyebrow">THÊM KHÔNG GIAN DỰ ÁN</div><h2>Cùng đội ngũ, dự án mới</h2><form id="projectForm"><label>Tên dự án<input name="name" maxlength="70" required placeholder="VD: Thương hiệu thời trang Mây"></label><label>Kiến thức ban đầu<textarea name="knowledge" maxlength="6000" placeholder="Sản phẩm, khách hàng, giọng thương hiệu, thông tin đã xác nhận..."></textarea></label><button class="primary full">Tạo dự án →</button></form>';document.body.append(projectDialog);projectDialog.querySelector('.close').onclick=()=>projectDialog.close();
const characterDialog=document.createElement('dialog');characterDialog.id='characterDialog';characterDialog.innerHTML='<button class="close" aria-label="Đóng">×</button><div class="eyebrow">TRẠM / CHARACTER SYSTEM / V1</div><h2>Phi Phi · Nhân vật gốc</h2><div class="character-preview"><img src="assets/phi-phi-master-v1.png" alt="Phi Phi xanh ngọc, khuôn mặt tròn bao quanh bởi các cánh hoa"/></div><p class="detail-text"><b>Giữ cố định:</b> đầu cánh hoa, mặt tròn xanh ngọc, mắt oval tối, nụ cười nhỏ, thân và tay chân ngắn.</p><p class="detail-text"><b>Thay đổi theo vai trò:</b> huy hiệu, dụng cụ và phụ kiện. Các phòng ban dùng cùng một nhân vật nền.</p><p class="muted">Bản demo có chuyển động chờ, xử lý và bàn giao bằng CSS. Đây chưa phải bộ rig nhân vật hoặc animation đi bộ hoàn chỉnh.</p>';document.body.append(characterDialog);characterDialog.querySelector('.close').onclick=()=>characterDialog.close();
const roles=['Điều phối','Research','Strategy','Content','Creative','SEO','Social','Ads','CRM','Analytics','Quality'];const tools=['🧭','🔎','♟','✎','🎨','🌱','💬','🎯','✉','▥','✓'];
const gfOutputs=[
'Brief mô phỏng: giới thiệu giá trị sử dụng GFKey và trợ lý Phi Phi. Đội nhận nhiệm vụ theo thứ tự nghiên cứu → chiến lược → nội dung → kênh → đo lường → kiểm duyệt. Chưa xác nhận ngân sách, KPI hoặc thời hạn thực tế.',
'Nguồn nội bộ nêu bốn nhóm: gia đình, chuyên gia/người tạo nội dung, cán bộ cấp xã, đối tác phân phối. Đề xuất thử nhóm người làm việc văn phòng trước. Đây là lựa chọn thử nghiệm, chưa có dữ liệu khảo sát chứng minh.',
'Góc tiếp cận đề xuất: bắt đầu bằng một việc hằng ngày người dùng muốn làm cùng trợ lý, rồi giải thích GFKey là quyền truy cập. Tránh gom mọi sản phẩm trong hệ sinh thái vào một lời hứa. Chưa đưa GFSign vào tính năng có sẵn.',
'BẢN NHÁP: “Một ngày làm việc, nhiều việc nhỏ. Tài liệu GreenFi giới thiệu Phi Phi cùng các trợ lý chuyên môn để hỗ trợ những nhu cầu khác nhau. Bạn muốn bắt đầu từ nội dung, học tập hay công việc? Tìm hiểu GFKey và quyền sử dụng phù hợp trước khi lựa chọn.”\nCần duyệt lại tính năng và điều kiện gói trước khi đăng.',
'Creative brief: Phi Phi xanh ngọc là nhân vật xuyên suốt. Tông mint, xanh nước nhạt và kem; nét hoạt hình mềm. Bố cục: một tác vụ cụ thể, một lợi ích có căn cứ, một lời mời tìm hiểu. Chưa xuất bản tài sản.',
'Cụm chủ đề đề xuất: GFKey là gì; Phi Phi hỗ trợ công việc như thế nào; hướng dẫn chọn gói; câu hỏi về quyền truy cập. Cần tra cứu ý định và lượng tìm kiếm trước khi ưu tiên, chưa có dữ liệu thứ hạng.',
'Lịch mô phỏng: thứ Hai giải thích một khái niệm GFKey; thứ Tư minh họa một tình huống dùng Phi Phi; thứ Sáu giải đáp câu hỏi. Facebook dùng bài ngắn, TikTok dùng kịch bản hướng dẫn. Tất cả cần duyệt trước khi đăng.',
'A/B đề xuất: A kể tình huống hỗ trợ công việc; B giới thiệu trợ lý chuyên môn. Dùng cùng đối tượng và định dạng khi thử. Chờ xác nhận trang đích, sự kiện đo lường và ngân sách; demo không tạo quảng cáo.',
'Chuỗi nháp: chào mừng → hỏi nhu cầu → gợi ý tài liệu hướng dẫn → giải đáp quyền sử dụng → hỏi phản hồi. Chỉ liên hệ khách đã đồng ý; không hứa thu nhập, lợi nhuận hoặc quyền lợi chưa xác nhận.',
'Khung đo lường: lượt xem nội dung, lượt truy cập trang sản phẩm, lượt tìm hiểu gói và phản hồi khách hàng. KPI chiến dịch cần xác nhận riêng, không lấy chỉ tiêu doanh số nhân sự trong quy chế làm kết quả Marketing.',
'Kiểm duyệt mô phỏng hoàn tất. Cần người xác nhận trước khi thực thi: tính năng thực có, bảng giá/gói hiện hành, quyền hình ảnh và ngân sách. Các câu về bảo mật tuyệt đối, thu nhập hoặc tính năng đề án không được tự động đưa ra công chúng.'];
render=function(){originalRender();document.body.classList.toggle('motion-paused',!motion);$('#projectSelect').innerHTML=projects.map(p=>`<option value="${esc(p.id)}" ${p.id===projectId?'selected':''}>${esc(p.name)}</option>`).join('');
$('#viewTitle').textContent=({office:'Văn phòng Phi Phi',tasks:'Công việc & bàn giao',results:'Kết quả mô phỏng',knowledge:'Tri thức dự án'})[document.querySelector('.nav.active')?.dataset.view||'office'];
$('#office').innerHTML='<div class="office-sign"><span>TRẠM MARKETING</span><small>KHÔNG GIAN ĐỘI NGŨ · '+esc(currentProject().name)+'</small></div>'+agents.map((a,i)=>`<button class="station ${i===0?'chief':''} ${i<state.step?'completed':''} ${state.title&&i===state.step?'busy':''}" data-agent="${i}" style="--delay:${-i*.43}s;--desk:${['#e6d6ec','#d1e8dc','#e9ddc9','#f0d9ce'][i%4]}"><span class="station-name">${roles[i]}<small>${a[0]} · Phi Phi</small></span><span class="desk-lamp"></span><span class="phi-character"><img src="assets/phi-phi-master-v1.png" alt=""/><span class="role-tool">${tools[i]}</span></span><span class="desk"><span class="monitor"><span></span></span><span class="keyboard"></span><span class="mug"></span></span><span class="station-status">${i<state.step?'✓ Đã bàn giao':state.title&&i===state.step?'••• Đang xử lý':'Sẵn sàng'}</span>${state.title&&i===state.step?'<span class="work-bubble">Đang làm việc<span>•••</span></span>':''}</button>`).join('')+'<div class="office-floor-note">🌿 Cùng một đội ngũ · Mỗi dự án một không gian tri thức</div>';
$('#motionToggle').textContent=motion?'Ⅱ Dừng chuyển động':'▶ Bật chuyển động';$('#sample').textContent='Chạy thử '+currentProject().name+' →';if(!state.title)$('#briefText').textContent='Chọn chiến dịch mẫu hoặc nhập brief riêng cho '+currentProject().name+'.';
if(state.step)$('#results').innerHTML=agents.slice(0,state.step).map((a,i)=>`<article class="result"><small>${esc(currentProject().name)} · ĐẦU RA MÔ PHỎNG</small><h3>${roles[i]} · ${a[7]}</h3><p>${esc(projectId==='gfkey'?gfOutputs[i]:a[8])}</p><small>Brief: ${esc(state.title)} · Chưa kết nối AI thật</small></article>`).join('');
$('#knowledge').innerHTML=`<article class="result"><div class="eyebrow">TRI THỨC / ${esc(currentProject().name)}</div><h3>Nguồn riêng cho từng dự án</h3><p class="muted">Đội ngũ dùng chung vai trò. Brief, tiến độ và kiến thức được lưu riêng theo dự án trên trình duyệt này.</p><label>Thông tin sản phẩm và giới hạn sử dụng<textarea id="knowledgeText" maxlength="12000">${esc(currentProject().knowledge)}</textarea></label><button id="saveKnowledge" class="primary">Lưu tri thức dự án</button><span id="knowledgeSaved" class="muted" role="status"></span></article>`;$('#saveKnowledge').onclick=()=>{currentProject().knowledge=$('#knowledgeText').value;persist();$('#knowledgeSaved').textContent=' Đã lưu trên trình duyệt';};
};
$('#projectSelect').onchange=e=>{stop();persist();projectId=e.target.value;state={...currentProject().campaign};render();};$('#addProject').onclick=()=>projectDialog.showModal();$('#projectForm').onsubmit=e=>{e.preventDefault();const form=new FormData(e.target);const name=form.get('name').trim();if(!name)return;stop();persist();const id='project-'+Date.now().toString(36);projects.push({id,name,knowledge:form.get('knowledge').trim(),campaign:emptyCampaign()});projectId=id;state=emptyCampaign();render();projectDialog.close();e.target.reset();};
$('#characterStandard').onclick=()=>characterDialog.showModal();$('#motionToggle').onclick=()=>{motion=!motion;document.body.classList.toggle('motion-paused',!motion);$('#motionToggle').textContent=motion?'Ⅱ Dừng chuyển động':'▶ Bật chuyển động';persist();};
$('#sample').onclick=()=>start(projectId==='gfkey'?'Giới thiệu GFKey qua tình huống dùng Phi Phi':'Chiến dịch giới thiệu '+currentProject().name,projectId==='gfkey'?'Mô phỏng kế hoạch nội dung GFKey cho người làm việc văn phòng. Kênh: Facebook và TikTok. Dựa trên nguồn GreenFi đã cung cấp, phân biệt mô tả sản phẩm, quy chế nội bộ và đề án. Mục tiêu thử: hoàn thành gói kế hoạch và bản nháp để người phụ trách duyệt. Chưa có ngân sách, KPI hoặc kết quả thực tế.':'Mô phỏng chiến dịch giới thiệu sản phẩm cho '+currentProject().name+'. Nghiên cứu → lập kế hoạch → nội dung → kênh → đo lường → duyệt. Hãy thay bằng brief và tri thức riêng; đây là mẫu quy trình cố định, chưa sinh nội dung bằng AI.');
document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>{document.querySelectorAll('[data-view]').forEach(n=>n.classList.toggle('active',n===b));['office','tasks','results','knowledge'].forEach(id=>$('#'+id).classList.toggle('hidden',id!==b.dataset.view));toolbar.classList.toggle('hidden',b.dataset.view!=='office');render();});
$('footer').textContent='TRẠM · Demo animation CSS · Mỗi dự án lưu riêng trên trình duyệt · Chưa kết nối AI hoặc dịch vụ bên ngoài.';
render();
